import{_ as r,o as t,c as a,ae as n}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Azure: exposure and health checks","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1008684393/references/azure.md","filePath":"adrs/1008684393/references/azure.md"}'),o={name:"adrs/1008684393/references/azure.md"};function i(s,e,c,l,h,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="azure-exposure-and-health-checks" tabindex="-1">Azure: exposure and health checks <a class="header-anchor" href="#azure-exposure-and-health-checks" aria-label="Permalink to &quot;Azure: exposure and health checks&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-11.</p><h2 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h2><p>Azure Load Balancer is <strong>public</strong> or <strong>internal</strong>, decided by whether its frontend IP is public or private; an internal load balancer &quot;can&#39;t accept incoming traffic from the internet&quot; (<a href="https://learn.microsoft.com/training/modules/intro-to-azure-load-balancer/3-how-azure-load-balancer-works" target="_blank" rel="noreferrer">How Azure Load Balancer works</a>). Application Gateway has a public frontend IP, a private one or both; Microsoft describes the private frontend as &quot;useful for internal line-of-business applications that aren&#39;t exposed to the internet&quot; (<a href="https://learn.microsoft.com/azure/application-gateway/configuration-frontend-ip" target="_blank" rel="noreferrer">Frontend IP configuration</a>).</p><p>On AKS, a <code>LoadBalancer</code> Service becomes internal with <code>service.beta.kubernetes.io/azure-load-balancer-internal: &quot;true&quot;</code> (<a href="https://learn.microsoft.com/azure/aks/internal-lb" target="_blank" rel="noreferrer">Internal load balancer</a>), and a <strong>private cluster</strong> keeps the API server on Private Link (<a href="https://learn.microsoft.com/azure/aks/private-clusters" target="_blank" rel="noreferrer">Private clusters</a>).</p><p>Container Apps ingress is <strong>external</strong>, shown as &quot;Accepting traffic from anywhere&quot;, or <strong>internal</strong>, shown as &quot;Limited to Container Apps Environment&quot;. Both are relative to the environment: an <strong>internal environment</strong> has no public endpoint, so an app with external ingress inside it is still not on the internet (<a href="https://learn.microsoft.com/azure/container-apps/ingress-overview" target="_blank" rel="noreferrer">Ingress</a>; <a href="https://learn.microsoft.com/azure/container-apps/networking" target="_blank" rel="noreferrer">Networking</a>). Internal ingress is not a complete boundary: &quot;An app with internal ingress can still receive traffic from outside the environment if it&#39;s referenced as a target in an environment-level HTTP route configuration&quot;. The app declares its audience and the environment decides whether that audience includes the internet.</p><p>Azure is not consistent between the words: &quot;internal&quot; usually labels who can reach something, &quot;private&quot; usually labels an IP or Private Link, and no page defines them as distinct levels.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>Microsoft&#39;s Zero Trust guidance moves access control &quot;away from the perimeter and closer to applications and resources&quot;, based on identity and device rather than network location (<a href="https://learn.microsoft.com/security/zero-trust/zero-trust-overview" target="_blank" rel="noreferrer">Zero Trust overview</a>). App Service authentication and managed identities provide that identity to users and workloads (<a href="https://learn.microsoft.com/azure/app-service/overview-authentication-authorization" target="_blank" rel="noreferrer">Authentication and authorization</a>; <a href="https://learn.microsoft.com/entra/identity/managed-identities-azure-resources/overview" target="_blank" rel="noreferrer">Managed identities</a>).</p><p>Staff tools sit behind Entra Application Proxy, whose connector only makes outbound connections (<a href="https://learn.microsoft.com/entra/identity/app-proxy/overview-what-is-app-proxy" target="_blank" rel="noreferrer">Application Proxy</a>), with Privileged Identity Management for just-in-time elevation (<a href="https://learn.microsoft.com/entra/id-governance/privileged-identity-management/pim-getting-started" target="_blank" rel="noreferrer">PIM</a>).</p><h2 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health checks&quot;">​</a></h2><p>Container Apps supports startup, liveness and readiness probes over HTTP or TCP, and adds default probes when ingress is enabled and none are defined (<a href="https://learn.microsoft.com/azure/container-apps/health-probes" target="_blank" rel="noreferrer">Health probes</a>).</p><p>App Service health check requests one configured path on every instance each minute and removes an instance from the load balancer after repeated failures (<a href="https://learn.microsoft.com/azure/app-service/monitor-instances-health-check" target="_blank" rel="noreferrer">Health check</a>).</p><p>Load Balancer probes come from <code>168.63.129.16</code>, which network security groups must not block (<a href="https://learn.microsoft.com/azure/load-balancer/manage-probes-how-to" target="_blank" rel="noreferrer">Manage health probes</a>). The Application Gateway Ingress Controller derives its probe from the Pod&#39;s <code>readinessProbe</code> or <code>livenessProbe</code>. Without either, it assumes the service answers at the <code>backend-path-prefix</code> annotation or the Ingress path, and it uses defaults, such as <code>/</code>, only for properties it cannot infer (<a href="https://learn.microsoft.com/azure/application-gateway/ingress-controller-add-health-probes" target="_blank" rel="noreferrer">Health probes with AGIC</a>). It reads only <code>httpGet</code> probes, and &quot;probing on a port other than the one exposed on the pod is currently not supported&quot;. A probe on another port is replaced by the <code>appgw.ingress.kubernetes.io/health-probe-path</code> and <code>appgw.ingress.kubernetes.io/health-probe-port</code> annotations on the Ingress, which default to <code>/</code> and <code>80</code> (<a href="https://learn.microsoft.com/azure/application-gateway/ingress-controller-annotations#custom-health-probe" target="_blank" rel="noreferrer">AGIC annotations</a>).</p><p>Microsoft documents the Health Endpoint Monitoring pattern but prescribes no path names (<a href="https://learn.microsoft.com/azure/architecture/patterns/health-endpoint-monitoring" target="_blank" rel="noreferrer">Health Endpoint Monitoring</a>).</p>',15)])])}const f=r(o,[["render",i]]);export{u as __pageData,f as default};
